[CmdletBinding()]
param(
    [Parameter(Mandatory)][string]$BundlePath,
    [Parameter(Mandatory)][string]$Destination,
    [Parameter(Mandatory)][string]$DependencyDirectory
)
$ErrorActionPreference = 'Stop'
$bundle = Get-Content -LiteralPath $BundlePath -Raw | ConvertFrom-Json
$destinationRoot = [IO.Path]::GetFullPath($Destination)
if (Test-Path -LiteralPath $destinationRoot) { throw 'Replay requires a fresh destination.' }
$dependencyRoot = (Resolve-Path -LiteralPath $DependencyDirectory).Path

# Verifies the captured compiled inputs; a fresh build needs its own applicability record.
foreach ($file in $bundle.provenance.dependencies) {
    if ((Get-FileHash -LiteralPath (Join-Path $dependencyRoot $file.name)).Hash -ne $file.sha256) { throw "Dependency differs: $($file.name)" }
}
New-Item -ItemType Directory -Path $destinationRoot | Out-Null

# Extracts only hash-checked bundle members beneath the new owned directory.
foreach ($file in $bundle.executableInputs) {
    $path = [IO.Path]::GetFullPath((Join-Path $destinationRoot $file.path))
    if (-not $path.StartsWith($destinationRoot + [IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)) { throw 'Bundle member escapes destination.' }
    $bytes = [Text.Encoding]::UTF8.GetBytes($file.utf8)
    if ([Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($bytes)) -ne $file.sha256) { throw "Embedded source hash differs: $($file.path)" }
    New-Item -ItemType Directory -Path (Split-Path $path -Parent) -Force | Out-Null
    [IO.File]::WriteAllBytes($path,$bytes)
}
$sourceHashes = @(Get-ChildItem $destinationRoot -File -Recurse | ForEach-Object { @{path=[IO.Path]::GetRelativePath($destinationRoot,$_.FullName);sha256=(Get-FileHash $_.FullName).Hash} })

# Relocates only the assembly directory directive; every dependency name and byte hash remains pinned.
foreach ($name in @('codec','permission')) {
    $path = Join-Path $destinationRoot "$name/References.fsx"
    $text = Get-Content -LiteralPath $path -Raw
    $text = [regex]::Replace($text,'(?m)^#I "[^"]+"',('#I "' + $dependencyRoot.Replace('\','/') + '"'))
    [IO.File]::WriteAllText($path,$text)
}
$runs = [Collections.Generic.List[object]]::new()

# Captures each native exit code and full output before the next stage can run.
function Invoke-Stage {
    param([string]$Name,[string]$Directory,[string]$Program,[string[]]$Arguments)
    Push-Location -LiteralPath $Directory
    try {
        $log = Join-Path $destinationRoot "$Name.log"
        & $Program @Arguments *> $log
        $exitCode = $LASTEXITCODE
        $runs.Add([ordered]@{name=$Name;program=$Program;arguments=$Arguments;workingDirectory=[IO.Path]::GetRelativePath($destinationRoot,$Directory);exitCode=$exitCode;logSha256=(Get-FileHash $log).Hash})
        if ($exitCode -ne 0) { throw "Stage failed: $Name; see $log" }
        Write-Output "$Name PASS"
    } finally { Pop-Location }
}
Invoke-Stage 'codec-fsharp' "$destinationRoot/codec" 'dotnet' @('fsi','--exec','Experiment.fsx')
Invoke-Stage 'codec-node' "$destinationRoot/codec" 'node' @('Check.cjs')
Invoke-Stage 'permission-fsharp' "$destinationRoot/permission" 'dotnet' @('fsi','--exec','Experiment.fsx')
foreach ($file in Get-ChildItem "$destinationRoot/generated/inputs" -File) {
    if ((Get-FileHash $file.FullName).Hash -ne (Get-FileHash "$destinationRoot/codec/$($file.Name)").Hash) { throw "New serializer output differs: $($file.Name)" }
}
Invoke-Stage 'generated-typescript' "$destinationRoot/generated" 'pwsh' @('-NoProfile','-File','Run.ps1')
$permissionResults = @(Get-Content "$destinationRoot/permission/results.json" -Raw | ConvertFrom-Json)
$generatedResults = @(Get-Content "$destinationRoot/generated/results.json" -Raw | ConvertFrom-Json)
$codecAssertions = @(Select-String -LiteralPath "$destinationRoot/codec-fsharp.log" -Pattern '^PASS:').Count
if ($permissionResults.Count -ne 25 -or $generatedResults.Count -ne 3 -or $codecAssertions -ne 22) { throw 'Unexpected result count.' }
$outputs = @(Get-ChildItem $destinationRoot -File -Recurse | Where-Object { $_.FullName -notmatch '[/\\]tooling[/\\]' } | Sort-Object FullName | ForEach-Object { [ordered]@{path=[IO.Path]::GetRelativePath($destinationRoot,$_.FullName).Replace('\','/');sha256=(Get-FileHash $_.FullName).Hash} })
$result = [ordered]@{
    capturedAtUtc=[DateTime]::UtcNow.ToString('o')
    platform=[Runtime.InteropServices.RuntimeInformation]::OSDescription
    dotnet=(& dotnet --version)
    node=(& node --version)
    powershell=$PSVersionTable.PSVersion.ToString()
    dependencyCount=@($bundle.provenance.dependencies).Count
    extractedInputHashes=$sourceHashes
    stages=$runs.ToArray()
    fsharpCodecAssertions=$codecAssertions
    permissionResults=$permissionResults
    generatedResults=$generatedResults
    outputs=$outputs
}
$result | ConvertTo-Json -Depth 30 | Set-Content -LiteralPath "$destinationRoot/replay-result.json"
Write-Output 'PASS: 22 F# assertions, 3 native Node cases, 25 permission cases, 2 fresh generated builds and 3 generated-codec cases.'

